import{_ as o,o as t,c as r,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"FR 3.6.11 — View Material Repository","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/05-content-task-workflow/3-6-11-view-material-repository/spec.md","filePath":"feature/srs/05-content-task-workflow/3-6-11-view-material-repository/spec.md"}'),i={name:"feature/srs/05-content-task-workflow/3-6-11-view-material-repository/spec.md"};function c(s,e,d,n,l,p){return t(),r("div",null,[...e[0]||(e[0]=[a('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-6-11-—-view-material-repository" tabindex="-1">FR 3.6.11 — View Material Repository <a class="header-anchor" href="#fr-3-6-11-—-view-material-repository" aria-label="Permalink to &quot;FR 3.6.11 — View Material Repository&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.6.11</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-063</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">View Material Repository</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Content &amp; Workflow (<code>FR 3.6</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-36</code></td></tr><tr><td style="text-align:left;"><strong>Document Status</strong></td><td style="text-align:left;">Implemented &amp; Verified</td></tr></tbody></table><h2 id="_1-objective-functional-scope" tabindex="-1">1. Objective &amp; Functional Scope <a class="header-anchor" href="#_1-objective-functional-scope" aria-label="Permalink to &quot;1. Objective &amp; Functional Scope&quot;">​</a></h2><p>Xem kho lưu trữ tư liệu sáng tạo của Workspace (View Material Repository — /workspaces/:id/library). Phân loại rõ ràng các nhóm tư liệu: (1) Ảnh/Video gốc chưa qua chỉnh sửa (RAW) kèm nhãn cảnh báo không được đăng trực tiếp (BR-36), (2) Ấn phẩm đã hậu kỳ hoàn chỉnh (Retouched/Final), và (3) Tài liệu nhận diện thương hiệu tham khảo do Client tải lên (Brand Assets for Reference). Hỗ trợ tìm kiếm và lọc theo phân loại, định dạng, người tải lên.</p><p><strong>Consolidated Implementation Scope:</strong> Folds in <code>view-material-repository</code>, <code>s3-folder-vault-security</code>, <code>material-preview-recovery</code>, and <code>library-simple-ux</code>: renders a two-zone hierarchical browser (<code>--- folder</code> above <code>--- file</code>) with Vietnamese-collation sorting (<code>newest</code>, <code>oldest</code>, <code>name_asc</code>, <code>name_desc</code>), <code>mediaKind</code> (<code>IMAGE</code>, <code>VIDEO</code>, <code>FILE</code>), <code>type</code> (<code>RAW</code>, <code>RETOUCHED</code>, <code>WATERMARKED</code> with non-blocking <code>&quot;Ảnh chưa chỉnh sửa&quot;</code> warning badge on <code>RAW</code> photos, <code>BR-36</code>), <code>purpose</code> (<code>MATERIAL</code> vs <code>BRAND_REFERENCE</code>), strict per-<code>clientProfileId</code> audience isolation (<code>INTERNAL</code> vs <code>CLIENT</code>), <code>Client</code> Personal Vault shared folders, zero-N+1 short-lived encrypted capability preview URLs (<code>/api/v1/repository-media</code> with automatic expired-URL recovery), and 5 GB S3 quota meter (<code>/storage-usage</code>) — with <code>SystemRole.ADMIN</code> blocked from viewing tenant media.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized actor (<code>Owner, Manager, Creator, Client</code>), I want to execute <strong>View Material Repository</strong> within my active Workspace with strict role/audience isolation, version/concurrency safety, and responsive feedback, so that content production workflows satisfy <code>BR-36</code> across Web and Mobile.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Workspace &amp; Role Authorization:</strong> Only authenticated actors holding <code>Owner, Manager, Creator, Client</code> in the target Workspace (plus <code>Guest</code> solely on public survey token endpoints in <code>3.6.25</code>) may invoke <code>GET /api/v1/workspaces/{workspaceId}/materials/browser · GET /api/v1/workspaces/{workspaceId}/materials · GET /{materialId} · POST /{materialId}/preview · GET /storage-usage · GET /api/v1/repository-media · GET /api/v1/client-vault/browser · GET /api/v1/workspaces/{workspaceId}/client-vault/browser</code>; revoked or cross-workspace callers are rejected (<code>401</code> / <code>403</code>).</li><li><strong>Core Domain &amp; Security Invariants (<code>BR-36</code>):</strong> <code>MaterialReadService, MaterialFolderService, MaterialPageQuery, MaterialAccessPolicy, RepositoryEnvelopeCrypto, RepositoryPlaintextCache, ClientVaultService, MaterialStorageUsageService</code> enforces all state-machine locks, audience visibility filters (<code>INTERNAL</code> vs per-<code>clientProfileId</code> <code>CLIENT</code>), storage/file validation rules, and Workspace timezone boundaries (<code>Asia/Ho_Chi_Minh</code> default).</li><li><strong>Persistence &amp; Envelope Contract:</strong> Operations on MongoDB <code>materials</code> (<code>MaterialDocument</code>), <code>material_folders</code> (<code>MaterialFolderDocument</code>), <code>client_vault_shares</code>; AWS S3 (<code>SYSTEM_S3</code> AES-256-GCM envelope-encrypted objects) return standardized <code>ApiResponse&lt;T&gt;</code> payloads (or authenticated binary/WebSocket frames where applicable) with deterministic <code>ErrorCode</code> mappings (<code>400 VALIDATION_ERROR</code>, <code>403 FORBIDDEN</code> / <code>WORKSPACE_ACCESS_DENIED</code>, <code>404 MATERIAL_NOT_FOUND</code> (<code>BR-20</code>, <code>BR-36</code>)).</li><li><strong>Internationalization (<code>vi</code> / <code>en</code>):</strong> Every label, badge, filter pill, modal prompt, empty state, and error toast uses parallel translation keys (<code>library.* / materials.*</code>) in <code>src/i18n/locales/vi/*.json</code> and <code>en/*.json</code> — zero hardcoded UI text.</li><li><strong>Semantic Light/Dark Theme &amp; Accessibility:</strong> Web (<code>src/pages/library/index.tsx</code>, <code>src/pages/library/components/{MediaTab,MaterialFolderSection,MaterialRepositoryCard,MaterialBadges,MediaDetailPanel,MaterialPreview,MaterialToolbar,MaterialTrashList}.tsx</code>, <code>src/services/materialService.ts</code>) and Mobile (<code>src/screens/more/MediaLibraryScreen.tsx</code>, <code>src/services/materialService.ts</code>, <code>src/utils/{repositoryLoader,repositoryFilters}.ts</code>) components use semantic CSS variables / <code>dark:</code> Tailwind tokens and <code>useTheme()</code> tokens, supporting keyboard navigation (<code>Enter</code>/<code>Escape</code>/focus return) and mobile viewports.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surface (<code>brandhub-web</code>):</strong> <code>src/pages/library/index.tsx</code>, <code>src/pages/library/components/{MediaTab,MaterialFolderSection,MaterialRepositoryCard,MaterialBadges,MediaDetailPanel,MaterialPreview,MaterialToolbar,MaterialTrashList}.tsx</code>, <code>src/services/materialService.ts</code></li><li><strong>Mobile Surface (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/MediaLibraryScreen.tsx</code>, <code>src/services/materialService.ts</code>, <code>src/utils/{repositoryLoader,repositoryFilters}.ts</code></li><li><strong>Required UI States:</strong><ul><li><strong>Loading / Pending:</strong> Skeleton placeholders, progress indicators for uploads/imports, and disabled duplicate-submit triggers.</li><li><strong>Empty State:</strong> Clear localized explanation with role-appropriate CTA — never substituting synthetic mock items.</li><li><strong>Conflict / Warning:</strong> Preserves unsaved user drafts on <code>409</code> conflicts and surfaces inline warnings (such as <code>RAW</code> unedited photo badges or compliance warnings).</li><li><strong>Error / Retry:</strong> Actionable inline/banner error state with retry capability.</li></ul></li></ul><h2 id="_5-api-realtime-contract" tabindex="-1">5. API &amp; Realtime Contract <a class="header-anchor" href="#_5-api-realtime-contract" aria-label="Permalink to &quot;5. API &amp; Realtime Contract&quot;">​</a></h2><ul><li><strong>Endpoints / Channels:</strong> <code>GET /api/v1/workspaces/{workspaceId}/materials/browser · GET /api/v1/workspaces/{workspaceId}/materials · GET /{materialId} · POST /{materialId}/preview · GET /storage-usage · GET /api/v1/repository-media · GET /api/v1/client-vault/browser · GET /api/v1/workspaces/{workspaceId}/client-vault/browser</code></li><li><strong>Controllers (<code>brandhub-business-service</code>):</strong> <code>MaterialFolderController.browse(), MaterialController.listMaterials() / getMaterial() / preview() / storageUsage() / listBrandAssets(), RepositoryEncryptedMediaController.read(), ClientVaultController.personal() / shared()</code></li><li><strong>Services:</strong> <code>MaterialReadService, MaterialFolderService, MaterialPageQuery, MaterialAccessPolicy, RepositoryEnvelopeCrypto, RepositoryPlaintextCache, ClientVaultService, MaterialStorageUsageService</code></li><li><strong>Repositories / Stores:</strong> MaterialMongoRepository (MongoDB <code>materials</code>, <code>material_folders</code>, <code>material_versions</code>, <code>client_vault_shares</code>)</li></ul><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Domain Error Codes:</strong> <code>400 VALIDATION_ERROR</code>, <code>403 FORBIDDEN</code> / <code>WORKSPACE_ACCESS_DENIED</code>, <code>404 MATERIAL_NOT_FOUND</code> (<code>BR-20</code>, <code>BR-36</code>).</li><li><strong>Audience &amp; Removed-Member Isolation:</strong> Removed or deactivated Workspace members lose read/write/WebSocket access immediately on the next request or STOMP frame; <code>Client</code> actors never see <code>INTERNAL</code>-only materials or other <code>ClientProfile</code> assets.</li><li><strong>Idempotency &amp; Concurrency:</strong> Optimistic revision checks (<code>workflowRevision</code>, <code>revision</code>, <code>clientMessageId</code>, <code>DriveOperationLease</code>) prevent race-condition overwrites and duplicate records on retry.</li></ul><h2 id="_7-definition-of-done-cross-references" tabindex="-1">7. Definition of Done &amp; Cross-References <a class="header-anchor" href="#_7-definition-of-done-cross-references" aria-label="Permalink to &quot;7. Definition of Done &amp; Cross-References&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Backend endpoints/handlers verified by automated tests (<a href="./test.html">test.md</a>), Web &amp; Mobile UI integrated against live APIs, <code>vi</code>/<code>en</code> locale parity verified, and Light/Dark themes verified.</li><li><strong>Out of Scope:</strong> Adjacent workflow capabilities covered by sibling FRs in <code>3.6.1–3.6.35</code> and social publishing execution in <code>3.8.1–3.8.15</code>.</li><li><strong>Related Documentation:</strong> <a href="./../../../../ba/05-content-task-workflow.html">BA Content &amp; Workflow Spec</a> · <a href="./../../../../ba/12-state-machines.html">State Machines</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a> · <a href="./test.html">Test Suite</a>.</li></ul>',18)])])}const m=o(i,[["render",c]]);export{h as __pageData,m as default};
